declare @osasco table (id int, codigo char(2), produto char(8), preco numeric(10,2))

/*
registros a serem inseridos ou atualizados
*/
------------

------------
declare @tot int, @i int, @ins int, @upd int
select  @tot = count(*) from @osasco

declare	@codigo char(2),
		@produto char(8),
		@preco numeric(10,2)

set @i = 1
set @ins = 0
set @upd = 0
while @i <= @tot
begin
	
	select	@codigo = a.codigo,
			@produto = a.produto,
			@preco = a.preco
	from @osasco a
	where a.id = @i

	if not exists(select 1 from produtos_precos where CODIGO_TAB_PRECO=@codigo and PRODUTO=@produto)
	--INSERT
	BEGIN

		values (@codigo, @produto, @preco, 0, '20171201','20171201')

		set @ins = @ins + 1

	END
	--UPDATE
	ELSE
	BEGIN

		update produtos_precos 
		set CODIGO_TAB_PRECO =@codigo,
		PRODUTO = @produto,
		PRECO1 = @preco,
		DATA_PARA_TRANSFERENCIA='20171201',
		DATA_CARGA_PRECOS='20171201'
		where CODIGO_TAB_PRECO = @codigo and PRODUTO = @produto

		set @upd = @upd + 1
	
	END

	set @i = @i + 1
end

select @ins as inseridos, @upd as atualizados
